1. Content Relevance (1-5): -5: Perfectly addresses all aspects of the prompt -4: Addresses most key aspects with minor omissions -3: Addresses main points but misses some important elements -2: Only partially relevant to the prompt -1: Largely irrelevant or off-topic 2. Content Quality (1-5): -5: Exceptional depth, insight, and originality -4: Strong analysis/creativity with good supporting details -3: Adequate development with some supporting elements -2: Superficial treatment with minimal development -1: Poor quality with major flaws in reasoning/execution 3. Coherence and Structure (1-5): -5: Excellent organization with seamless flow -4: Clear structure with minor transition issues -3: Generally organized but some awkward transitions -2: Poorly organized with frequent disconnects -1: Chaotic or illogical structure 4. Reference Comparison (1-5): -5: Matches or exceeds expected quality for this type of task -4: Slightly below ideal but strong performance -3: Moderately below ideal but acceptable -2: Significantly below expected quality -1: Far below acceptable quality standards Please provide: 1. Numeric scores for each dimension (1-5) 2. Brief justification for each score (1-2 sentences) 3. Total score (sum of the four dimensions, maximum 20 points) 4. Summary feedback (2-3 sentences) Format your response as: Content Relevance: [score] points -Justification: [brief explanation] Content Quality: [score] points -Justification: [brief explanation] Coherence: [score] points -Justification: [brief explanation] Reference Comparison: [score] points -Justification: [brief explanation] novel = "" chapter_count = 10 # Adjust as needed for i in range(chapter_count): chapter = await self.custom( input=problem + f"
Outline: {outline['response']}
Character Profiles: {character_profiles['response']}
Chapter Number: {i+1}", ↩→ ↩→ instruction=prompt_custom.CHAPTER_PROMPT ) novel += f"

Chapter {i+1}

{chapter['response']}" return novel, self.llm.cost_manager.total_cost

Operators class ContextualGenerate(Operator): async def __call__(self, problem, context, mode: str = None): prompt = CONTEXTUAL_GENERATE_PROMPT.format(problem_description=problem, thought=context) ↩→ fill_kwargs = {"context": prompt, "llm": self.llm} if mode: fill_kwargs["mode"] = mode node = await ActionNode.from_pydantic(GenerateOp).fill( ** fill_kwargs) response = node.instruct_content.model_dump() return response class CodeGenerate(Operator): async def __call__(self, problem, function_name, mode: str = None): prompt = GENERATE_CODEBLOCK_PROMPT.format(problem_description=problem) fill_kwargs = {"context": prompt, "llm": self.llm, "function_name": function_name} ↩→ if mode: fill_kwargs["mode"] = mode node = await ActionNode.from_pydantic(CodeGenerateOp).fill( ** fill_kwargs) response = node.instruct_content.model_dump() return response class Format(Operator): async def __call__(self, problem, solution, mode: str = None): prompt = FORMAT_PROMPT.format(problem_description=problem, solution=solution) fill_kwargs = {"context": prompt, "llm": self.llm} if mode: fill_kwargs["mode"] = mode node = await ActionNode.from_pydantic(FormatOp).fill( ** fill_kwargs) response = node.instruct_content.model_dump() return response class Review(Operator): async def __call__(self, problem, solution, mode: str = None): prompt = REVIEW_PROMPT.format(problem_description=problem, solution=solution, criteria=self.criteria) ↩→ fill_kwargs = {"context": prompt, "llm": self.llm} if mode: fill_kwargs["mode"] = mode node = await ActionNode.from_pydantic(ReviewOp).fill( ** fill_kwargs) response = node.instruct_content.model_dump() return response class Revise(Operator): async def __call__(self, problem, solution, feedback, mode: str = None): prompt = REVISE_PROMPT.format(problem_description=problem, solution=solution, feedback=feedback) ↩→ fill_kwargs = {"context": prompt, "llm": self.llm} if mode: fill_kwargs["mode"] = mode node = await ActionNode.from_pydantic(ReviseOp).fill( ** fill_kwargs) response = node.instruct_content.model_dump() return response class Ensemble(Operator): async def __call__(self, solutions: List[str], problem: str, mode: str = None): answer_mapping = {} solution_text = "" for index, solution in enumerate(solutions): answer_mapping[chr(65 + index)] = index solution_text += f"{chr(65 + index)}: 
{str(solution)}


" fill_kwargs = {"context": prompt, "llm": self.llm, "function_name": "solve"} if mode: fill_kwargs["mode"] = mode node = await ActionNode.from_pydantic(CodeGenerateOp).fill( ** fill_kwargs) response = node.instruct_content.model_dump() return response async def __call__(self, problem: str, analysis: str = "None"): code = None for i in range(3): code = await self.code_generate(problem, analysis, feedback, mode="code_fill") ↩→ code = code["code"] status, output = await self.exec_code(code)

↩→ ↩→ ↩→ Problem: {input} Generate 3-5 additional test cases as assert statements: """ async def __call__(self, problem: str, entry_point: str): solutions = [] for _ in range(3): # Generate 3 solutions solution = await self.custom_code_generate(problem=problem, entry_point=entry_point, instruction=prompt_custom.CODE_GENERATE_PROMPT) ↩→ solutions.append(solution['response']) best_solution = await self.sc_ensemble(solutions=solutions, problem=problem) # Generate additional test cases additional_tests = await self.custom(input=f"Problem: {problem}
Solution: {best_solution['response']}", instruction=prompt_custom.GENERATE_TESTS_PROMPT) ↩→ # Combine original problem and additional tests enhanced_problem = f"{problem}

Additional test cases:
{additional_tests['response']}" ↩→ test_result = await self.test(problem=enhanced_problem, solution=best_solution['response'], entry_point=entry_point) ↩→ if test_result['result']: return test_result['solution'], self.llm.cost_manager.total_cost else: # If the test fails, try to fix the solution fixed_solution = await self.custom(input=f"Problem: {problem}
Failed solution: {best_solution['response']}
Error: {test_result['solution']}", instruction=prompt_custom.FIX_CODE_PROMPT) ↩→ ↩→ return fixed_solution['response'], self.llm.cost_manager.total_cost

↩→ solution2 = await self.custom(input=problem, instruction=prompt_custom.SOLVE_APPROACH2_PROMPT) ↩→ solution3 = await self.custom(input=problem, instruction=prompt_custom.SOLVE_APPROACH3_PROMPT) ↩→ combined_solutions = f"Solution 1: {solution1['response']}
Solution 2: {solution2['response']}
Solution 3: {solution3['response']}" ↩→ final_solution = await self.custom(input=problem + "
" + combined_solutions, instruction=prompt_custom.COMPARE_AND_SELECT_PROMPT) ↩→ return final_solution['response'], self.llm.cost_manager.total_cost
